        self.personUserId = personUserId
        self.reason = reason
        self.deviceIds = deviceIds
        self.recoveryEpoch = recoveryEpoch
        self.seq = seq
        self.observedSeq = observedSeq
        self.acknowledged = acknowledged
    }
}



