/**
 * Exact frames to emit after accepting a peer's DIGEST.
 *
 * The three lists remain separate for diagnostics, but are selected by one
 * core operation so neither platform can accidentally omit a traffic class.
 */
public struct CoreDigestSprayPlan {
    public var carriedFrames: [Data]
    public var ownOutboundFrames: [Data]
    public var ownReceiptFrames: [Data]
    /**
     * Hidden-kind msg_ids newly included for a peer that can't ack hidden
     * kinds. The shell records these on the peer's router entry
     * (`record_hidden_offered`) after sending, so the next plan for this
     * session excludes them — the once-per-session re-spray bound. Empty
     * when the peer advertised CAP_ACKS_HIDDEN_KINDS.
     */
    public var offeredHiddenMsgIds: [Data]
    /**
     * Resume point for this link session's next carried-lane round: the last
     * carried row this plan offered, or `None` if it offered none. The shell
     * hands it straight back via `record_carried_progress`. It is offering
     * bookkeeping only, never a delete signal.
     */
    public var nextCarriedCursor: CoreCarriedCursor?
    /**
     * Whether the carried lane reached the tail of the queue this round --
     * i.e. this peer has now been offered everything it is eligible for, so
     * the lane can park until the re-walk cooldown elapses.
     */
    public var carriedExhausted: Bool
    /**
     * What each lane advertises and what it would cost, handed straight to
     * [`crate::CoreSprayPolicy::admit_plan`]. That call suppresses, per lane,
     * a set the peer was already offered inside the re-offer interval -- the
     * 28 consecutive byte-identical sprays of issue #280. Computed here
     * rather than in the shells so both platforms compare the same thing, and
     * kept per lane rather than folded into one digest because the recorded
     * shape was an invariant authored lane beside a carried lane walking a
     * cursor: a union digest changes on every page turn and so suppresses
     * nothing. See [`crate::CoreSprayLanePlan`].
     */
    public var lanes: CoreSprayPlanShape
    /**
     * Total sealed bytes this plan would put on the wire, across all lanes.
     * Diagnostics: what the per-link burst allowance is actually charged is
     * the admitted lanes' bytes, which `admit_plan` computes from `lanes`.
     */
    public var planBytes: UInt64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(carriedFrames: [Data], ownOutboundFrames: [Data], ownReceiptFrames: [Data], 
        /**
         * Hidden-kind msg_ids newly included for a peer that can't ack hidden
         * kinds. The shell records these on the peer's router entry
         * (`record_hidden_offered`) after sending, so the next plan for this
         * session excludes them — the once-per-session re-spray bound. Empty
         * when the peer advertised CAP_ACKS_HIDDEN_KINDS.
         */offeredHiddenMsgIds: [Data], 
        /**
         * Resume point for this link session's next carried-lane round: the last
         * carried row this plan offered, or `None` if it offered none. The shell
         * hands it straight back via `record_carried_progress`. It is offering
         * bookkeeping only, never a delete signal.
         */nextCarriedCursor: CoreCarriedCursor?, 
        /**
         * Whether the carried lane reached the tail of the queue this round --
         * i.e. this peer has now been offered everything it is eligible for, so
         * the lane can park until the re-walk cooldown elapses.
         */carriedExhausted: Bool, 
        /**
         * What each lane advertises and what it would cost, handed straight to
         * [`crate::CoreSprayPolicy::admit_plan`]. That call suppresses, per lane,
         * a set the peer was already offered inside the re-offer interval -- the
         * 28 consecutive byte-identical sprays of issue #280. Computed here
         * rather than in the shells so both platforms compare the same thing, and
         * kept per lane rather than folded into one digest because the recorded
         * shape was an invariant authored lane beside a carried lane walking a
         * cursor: a union digest changes on every page turn and so suppresses
         * nothing. See [`crate::CoreSprayLanePlan`].
         */lanes: CoreSprayPlanShape, 
        /**
         * Total sealed bytes this plan would put on the wire, across all lanes.
         * Diagnostics: what the per-link burst allowance is actually charged is
         * the admitted lanes' bytes, which `admit_plan` computes from `lanes`.
         */planBytes: UInt64) {
        self.carriedFrames = carriedFrames
        self.ownOutboundFrames = ownOutboundFrames
        self.ownReceiptFrames = ownReceiptFrames
        self.offeredHiddenMsgIds = offeredHiddenMsgIds
        self.nextCarriedCursor = nextCarriedCursor
        self.carriedExhausted = carriedExhausted
        self.lanes = lanes
        self.planBytes = planBytes
    }
}



extension CoreDigestSprayPlan: Equatable, Hashable {
    public static func ==(lhs: CoreDigestSprayPlan, rhs: CoreDigestSprayPlan) -> Bool {
        if lhs.carriedFrames != rhs.carriedFrames {
            return false
        }
        if lhs.ownOutboundFrames != rhs.ownOutboundFrames {
            return false
        }
        if lhs.ownReceiptFrames != rhs.ownReceiptFrames {
            return false
        }
        if lhs.offeredHiddenMsgIds != rhs.offeredHiddenMsgIds {
            return false
        }
        if lhs.nextCarriedCursor != rhs.nextCarriedCursor {
            return false
        }
        if lhs.carriedExhausted != rhs.carriedExhausted {
            return false
        }
        if lhs.lanes != rhs.lanes {
            return false
        }
        if lhs.planBytes != rhs.planBytes {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(carriedFrames)
        hasher.combine(ownOutboundFrames)
        hasher.combine(ownReceiptFrames)
        hasher.combine(offeredHiddenMsgIds)
        hasher.combine(nextCarriedCursor)
        hasher.combine(carriedExhausted)
        hasher.combine(lanes)
        hasher.combine(planBytes)
    }
}


