    public static func ==(lhs: CoreInboundOutcome, rhs: CoreInboundOutcome) -> Bool {
        if lhs.disposition != rhs.disposition {
            return false
        }
        if lhs.deliveredPayloads != rhs.deliveredPayloads {
            return false
        }
        if lhs.deliveredSender != rhs.deliveredSender {
