        if lhs.droppedBlocked != rhs.droppedBlocked {
            return false
        }
        if lhs.syncPeerDigest != rhs.syncPeerDigest {
            return false
        }
        if lhs.commit != rhs.commit {
            return false
        }
        if lhs.work != rhs.work {
            return false
        }
        return true
