        self.firstIndex = firstIndex
        self.rows = rows
    }
}



extension CoreRelayShadowMismatch: Equatable, Hashable {
    public static func ==(lhs: CoreRelayShadowMismatch, rhs: CoreRelayShadowMismatch) -> Bool {
        if lhs.kind != rhs.kind {
