    public func hash(into hasher: inout Hasher) {
        hasher.combine(outcome)
        hasher.combine(appliedEntries)
        hasher.combine(throughSeq)
        hasher.combine(ownRoster)
        hasher.combine(peerDigest)
        hasher.combine(relayCredential)
    }
