@_documentation(visibility: private)
#endif
public func FfiConverterTypeShipWifiObservationEvent_lift(_ buf: RustBuffer) throws -> ShipWifiObservationEvent {
    return try FfiConverterTypeShipWifiObservationEvent.lift(buf)
}

